import React, { useState } from 'react'

const BlogForm = ({
  addBlog,
  newTitle,
  handleTitleChange,
  newAuthor,
  handleAuthorChange,
  newUrl,
  handleUrlChange,
  newImage,
  handleImageChange
}) => {

  const sendImage = () => {
    const files = document.getElementById('upload-image').files
    const file = files[0]
    console.log(file)

    if(file === null){
      return alert('No file selected.')
    }
    getSignedRequest(file)
  }

  const getSignedRequest = (file) => {
    const xhr = new XMLHttpRequest()
    xhr.open('GET', `/sign-s3?file-name=${file.name}&file-type=${file.type}`)
    xhr.onreadystatechange = () => {
      if(xhr.readyState === 4){
        if(xhr.status === 200){
          const response = JSON.parse(xhr.responseText)
          uploadFile(file, response.signedRequest, response.url)
        }
        else{
          alert('Could not get signed URL.')
        }
      }
    }
    xhr.send()
  }

  const uploadFile = (file, signedRequest, url) => {
    const xhr = new XMLHttpRequest()
    xhr.open('PUT', signedRequest)
    xhr.onreadystatechange = () => {
      if(xhr.readyState === 4){
        if(xhr.status === 200){
          alert('ok')
        }
        else{
          alert('Could not upload file.')
        }
      }
    }
    xhr.send(file)
  }

  return (
    <div>
      <form onSubmit={addBlog}>
        <div>
          <h3>Add new blog</h3>
          <p>Title:
            <input
              id='title'
              value={newTitle}
              onChange={handleTitleChange}
            />
          </p>
        </div>
        <div>
          <p>Author:
            <input
              id='author'
              value={newAuthor}
              onChange={handleAuthorChange}
            />
          </p>
        </div>
        <div>
          <p>Url:
            <input
              id='url'
              value={newUrl}
              onChange={handleUrlChange}
            />
          </p>
        </div>
        <div className="process">
          <h4 className="process_heading">Image</h4>
          <p className="process_details">Upload image to server</p>

          <input type="file" className="process_upload-btn" onChange={handleImageChange} />
          <img src={newImage !== undefined ? newImage.multerImage : null} alt="upload-image" id="upload-image" className="process_image" />
        </div>
        <br></br>
        <button class="btn btn-warning" type="submit" id="save_blog">create</button>
      </form>
      <br></br>
    </div>
  )}

export default BlogForm