import React, { useState, useEffect } from 'react'
import Blog from './components/Blog'
import User from './components/User'
import BlogDetails from './components/BlogDetails'
import Notification from './components/Notification'
import blogService from './services/blogs'
import loginService from './services/login'
import userService from './services/users'
import imageService from './services/images'
import BlogForm from './components/BlogForm'
import Togglable from './components/Togglable'
import BlogView from './components/BlogView'
import Menu from './components/Menu'
import Users from './components/Users'
import { TextField } from '@material-ui/core'
import {
  BrowserRouter as Router,
  Switch, Route, Link
} from 'react-router-dom'
import DefaultImg from './assets/default-img.jpg'

let timeoutID

const App = () => {
  const [blogs, setBlogs] = useState([])
  const [newTitle, setNewTitle] = useState('')
  const [newAuthor, setNewAuthor] = useState('')
  const [newUrl, setNewUrl] = useState('')
  const [newImage, setNewImage] = useState({ multerImage: DefaultImg })
  const [message, setMessage] = useState(null)
  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('')
  const [user, setUser] = useState(null)
  const blogFormRef = React.createRef()
  const blogRef = React.createRef()
  const [users, setUsers] = useState([])

  useEffect(() => {
    userService.getAll().then(users => {
      console.log('users comin')
      console.log(users)
      setUsers(users)
    })
  }, [])

  useEffect(() => {
    blogService.getAll().then(blogs =>
      setBlogs( blogs.sort(function(a,b) {
        return b.likes-a.likes
      })))
  }, [])

  useEffect(() => {
    const loggedUserJSON = window.localStorage.getItem('loggedUser')
    if (loggedUserJSON) {
      const user = JSON.parse(loggedUserJSON)
      setUser(user)
      blogService.setToken(user.token)
      imageService.setToken(user.token)
    }
  }, [])

  const handleLogin = async (event) => {
    event.preventDefault()
    console.log('logging in with', username)
    try {
      const user = await loginService.login({
        username, password
      })
      window.localStorage.setItem(
        'loggedUser', JSON.stringify(user)
      )
      blogService.setToken(user.token)
      imageService.setToken(user.token)
      setUser(user)
      setUsername('')
      setPassword('')
      const newMessage = {
        type: 'success',
        text: `Welcome, ${username}`
      }
      setMessage(newMessage)
      setTimeout(() => { setMessage(null) }, 4000)
    } catch (exception) {
      const newMessage = {
        type: 'error',
        text: 'Wrong credentials'
      }
      setMessage(newMessage)
      setTimeout(() => { setMessage(null) }, 4000)
    }
  }

  const handleLogout = async (event) => {
    event.preventDefault()
    console.log('logging out with', username)
    window.localStorage.clear()
    setUser(null)
    blogService.setToken('')
    imageService.setToken('')
  }

  const loginForm = () => (
    <div>
      <h2>Log in to application</h2>
      <form onSubmit={handleLogin}>
        <div>
          <TextField label="username"
            id="username"
            type="text"
            value={username}
            name="Username"
            onChange={({ target }) => setUsername(target.value)}
          />
        </div>
        <div>
          <TextField label="password"
            id="password"
            type="password"
            value={password}
            name="Password"
            onChange={({ target }) => setPassword(target.value)}
          />
        </div>
        <button type="submit" class="btn btn-success" id="login-button">login</button>
      </form>
    </div>
  )

  const blogForm = () => (
    <Togglable buttonLabel='new blog' cancelLabel='cancel' ref={blogFormRef}>
      <BlogForm
        addBlog={addBlog}
        newTitle={newTitle}
        handleTitleChange={handleTitleChange}
        newAuthor={newAuthor}
        handleAuthorChange={handleAuthorChange}
        newUrl={newUrl}
        handleUrlChange={handleUrlChange}
        newImage={newImage}
        handleImageChange={handleImageChange}
      />
    </Togglable>
  )

  const addBlog = (event) => {
    event.preventDefault()
    const blogObject = {
      title: newTitle,
      author: newAuthor,
      url: newUrl,
      id: blogs.length + 1,
    }
    blogObject.user=user
    console.log(user)

    console.log(newImage)

    blogObject.image=newImage.imageObject
    console.log(blogObject.image)


    blogService
      .create(blogObject)
      .then(returnedBlog => {
        console.log(returnedBlog.user)
        console.log(returnedBlog.image)
        setBlogs(blogs.concat(returnedBlog))
      })

    const newMessage = {
      type: 'success',
      text: `New blog ${newTitle} created`
    }
    setMessage(newMessage)
    blogFormRef.current.toggleVisibility()
    setTimeout(() => { setMessage(null) }, 4000)
    setNewTitle('')
    setNewAuthor('')
    setNewUrl('')
    setDefaultImage()
  }

  const handleLike = (event) => {
    event.preventDefault()
    const id = event.target.id

    const blogToUpdate = blogs.find(blog => blog.id === id)
    blogToUpdate.likes = blogToUpdate.likes+1
    blogService.update(id, blogToUpdate)
      .then(response => {
        setBlogs(blogs.map(blog => blog.id !== id ? blog : response))
      }).catch(error => {
        console.log(error.response.data)
      })
    const newMessage = {
      type: 'success',
      text: `Blog ${blogToUpdate.title} updated`
    }
    setMessage(newMessage)
    clearTimeout(timeoutID)
    timeoutID = setTimeout(() => { setMessage(null) }, 4000)
    setNewTitle('')
    setNewAuthor('')
    setNewUrl('')
  }

  const handleDeleteClick = (blog) => {
    console.log('deleting', blog.id)
    const title = blog.title
    const author = blog.author
    if (window.confirm(`Delete blog ${title} by ${author}?`)) {
      deleteBlog(blog)
    }
  }

  const deleteBlog = (blog) => {
    blogService.deleteBlog(blog.id)
      .then(response => {
        const updatedBlogs = blogs.filter(p => p.id !== blog.id)
        setBlogs(updatedBlogs)
      }).then(e => {
        const newMessage = {
          type: 'success',
          text: `Deleted ${blog.name}`
        }
        setMessage(newMessage)
        setTimeout(() => { setMessage(null) }, 4000)
      }).catch(error => {
        const newMessage = {
          type: 'error',
          text: `${blog.title} has already been removed from the server!`
        }
        setMessage(newMessage)
        setTimeout(() => { setMessage(null) }, 4000)
      })
  }


  const handleTitleChange = (event) => {
    setNewTitle(event.target.value)
  }

  const handleAuthorChange = (event) => {
    setNewAuthor(event.target.value)
  }

  const handleUrlChange = (event) => {
    setNewUrl(event.target.value)
  }

  const handleImageChange = (e) => {
    const imageFormObj = new FormData()

    imageFormObj.append('imageName', 'multer-image-' + Date.now())
    imageFormObj.append('imageData', e.target.files[0])

    const multerImage = URL.createObjectURL(e.target.files[0])
    imageFormObj.append('multerImage', multerImage)

    imageService.create(imageFormObj)
      .then((data) => {
        console.log(data)
        setNewImage({
          multerImage: multerImage,
          imageObject: { id: data.id, imageData: data.imageData, imageName: data.imageName }
        })
        if (data) {
          alert('Image has been successfully uploaded using multer')
          console.log(newImage)

        }
      })
      .catch((err) => {
        alert('Error while uploading image using multer')
        console.log(err)
      })
  }

  const setDefaultImage = () => {
    setNewImage({
      multerImage: DefaultImg
    })
  }

  return (
    <div>
      <Router>
        <Menu user={user} handleLogout={handleLogout} />
        <Notification message={message} />
        <Switch>
          <Route path="/blogs/:id" render={({ match }) =>
            <BlogView id={match.params.id} blogs={blogs} handleLike={handleLike} />
          }>
          </Route>
          <Route path="/users/:id" render={({ match }) =>
            <User id={match.params.id} users={users}/>
          }>
          </Route>
          <Route path="/users">
            <Users users={users}/>
          </Route>
          <Route path="/">
            {user === null ?
              loginForm() :
              <div>
                {blogForm()}
                <br></br>
                <div className="blogs">
                  {blogs.map(blog =>
                    <div className="blog">
                      <Blog key={blog.id} blog={blog} handleDeleteClick={handleDeleteClick} user={user} />
                      <Togglable buttonLabel='view' cancelLabel='hide' className="view" ref={blogRef}>
                        <BlogDetails key={blog.id} blog={blog} handleLike={handleLike} />
                      </Togglable>
                    </div>
                  )}
                </div>
              </div>
            }
          </Route>
        </Switch>
      </Router>
    </div>
  )
}

export default App