import React from 'react'
const BlogDetails = ({ blog, handleLike }) => (
  <div>
    <p>{blog.url}</p>
    <form onSubmit={handleLike} id={blog.id}>
      <p>likes: {blog.likes}
        <button class="btn btn-success" type="submit">like</button>
      </p>
    </form>

    <p>{blog.author}</p>
  </div>
)

export default BlogDetails