import React from 'react'

const User = ({ id, users }) => {
  const user = users.filter(u => u.id === id)[0]
  let blogs = []

  if (user === undefined) {
    return null
  } else {
    blogs = user.blogs
  }
  return (
    <div>
      <h3>{user.name}</h3>
      <h4>added blogs:</h4>
      <ul>
        {blogs.map(blog =>
          <li key={blog.id}>{blog.title}</li>)}
      </ul>
    </div>
  )
}

export default User