import React from 'react'

const BlogView = ({ id, blogs, handleLike }) => {
  const blog = blogs.filter(b => b.id === id)[0]
  console.log(blog.image)
  console.log(blog.user)

  return (
    <div>
      <h3>{blog.title} {blog.author}</h3>
      <p>{blog.url}</p>
      <a href={blog.url}></a>
      <p>{blog.likes} likes </p>
      <img src={blog.image !== undefined ? `${blog.image.imageData}` : ''} alt="image" />
      <button class="btn btn-success" onClick={handleLike} id={blog.id}>like</button>
    </div>
  )
}


export default BlogView