import React from 'react'
import { Link } from 'react-router-dom'

const Blog = ({ blog, handleDeleteClick, user }) => (
  <div>
    <Link to={`/blogs/${blog.id}`}>{blog.title}</Link>
    <img src={blog.image !== undefined ? `${blog.image.imageData}` : ''} alt="image" className="process__image" />
    <form>
      {user !== undefined && blog.user !== undefined && user.username === blog.user.username &&
      <button class="btn btn-danger" onClick={() =>
        handleDeleteClick(blog)}>
        delete
      </button>
      }
    </form>
  </div>
)

export default Blog